// Parse AI response and attach request_id for database update
   const aiText = $json?.output?.[0]?.content?.find(c => c.type === "output_text")?.text
     ?? $json?.output?.[0]?.content?.[0]?.text
     ?? $json?.text
     ?? $json?.response
     ?? "";

   if (!String(aiText).trim()) {
     throw new Error("Could not find AI text in response");
   }

   // Clean markdown fences
   let cleanText = String(aiText)
     .trim()
     .replace(/^```(?:json)?\s*/i, "")
     .replace(/```$/i, "")
     .trim();

   // Parse JSON
   let aiAnalysis;
   try {
     aiAnalysis = JSON.parse(cleanText);
   } catch (e) {
     throw new Error("AI output is not valid JSON. First 300 chars:\n" + cleanText.slice(0, 300));
   }

   // Get request_id from the Fetch node
   const request_id = $('Fetch Complete Ticker Data').item.json.request_id;

   if (!request_id) {
     throw new Error("Missing request_id from input data");
   }

   return [{
     json: {
       request_id: request_id,
       ai_analysis_payload: aiAnalysis,
       updated_at: new Date().toISOString()
     }
   }];

